const body = $('Set Fields').first().json.messageBody.trim();

const match = body.match(/^\/desactivar\s+(\+?\d+)$/i);

if (!match) {
  return [{ json: { valido: false, session_id: null } }];
}

return [{ json: {
  valido: true,
  session_id: match[1]
}}];

