const input = $input.first().json;
const mensaje = (input.output || input.text || input.texto_limpio || '').trim();

if (!mensaje) {
  return [{ json: { part1: '', part2: '', part3: '' } }];
}

const partes = mensaje.split('|||').map(p => p.trim()).filter(p => p.length > 0);

return [{
  json: {
    part1: partes[0] || '',
    part2: partes[1] || '',
    part3: partes[2] || ''
  }
}];

const filas = $input.all();
const hayFila = filas.length > 0 && filas[0].json.chatId !== undefined && filas[0].json.chatId !== '';

let numeroOrden;

if (hayFila) {
  numeroOrden = filas[0].json.numeroOrden;
} else {
  numeroOrden = Math.floor(Math.random() * 100) + 1;
}

return [{ json: {
  primer_mensaje: !hayFila,
  numeroOrden,
}}];

const count = parseInt($input.first().json.COUNT) || 0;

return [{ json: {
  COUNT: count
}}];
